import {profile,projects,skills,leadership} from './data.js';
import {motionPanel,mountMotion} from './motion.js';
import {loadGithub} from './github.js';
import {siteConfig} from './config.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'';
const bytes=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.ceil(n/1024)+' KB';
const button=(label,action,cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const tags=a=>`<div class="tags">${a.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`;
const pill=(s,c='')=>`<span class="status-pill ${c}">${esc(s)}</span>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">[ + ]</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
const fields=['objective','work','results','problems','next'];
const labels={objective:'Objective',work:'Work done',results:'Results',problems:'Problems',next:'Next steps'};
let db,state={logs:[],notes:[],files:[],goals:[],announcements:[]},route='',filter='All',search='',editorMode='visual',recorder=null,stream=null,recordChunks=[],recordProject=null,recordStarted=0,recordTimer=null,urls=[],storageError=false;
let deployedContent={logs:[],notes:[],announcements:[]};
function publicRecords(store){const local=state[store].filter(x=>x.published);const localIds=new Set(local.map(x=>x.id));return [...(deployedContent[store]||[]).filter(x=>!localIds.has(x.id)),...local];}
const schema=['logs','notes','files','goals','announcements','blobs'];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open('yash-engineering-preview',1);r.onupgradeneeded=()=>schema.forEach(s=>r.result.createObjectStore(s,{keyPath:'id'}));r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function tx(store,method,value){return new Promise((resolve,reject)=>{if(!db)return reject(new Error('Device storage is unavailable.'));const t=db.transaction(store,method==='get'||method==='getAll'?'readonly':'readwrite');const r=t.objectStore(store)[method](value);t.oncomplete=()=>resolve(r.result);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('Storage transaction cancelled'));});}
async function load(){await Promise.all(Object.keys(state).map(async k=>state[k]=await tx(k,'getAll')));}
async function persist(store,value){await tx(store,'put',value);await load();}
const projectName=id=>projects.find(p=>p.id===id)?.name||'General';
const optionProjects=(id='')=>`<option value="">General / no project</option>${projects.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}`;
const head=(eyebrow,title,desc='')=>`<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;
function art(type='maze',id='art'){let body='';if(type==='maze')body=`<g stroke="#536e60" stroke-width="2" fill="none"><path d="M55 50h260v170H55z M55 90h40v90h40v-50h45v90 M95 50v40h85v40h50v-40h40v90h45 M135 50v40 M55 130h40 M55 180h40 M135 180h45 M230 130v90 M270 50v40 M270 180v40 M180 50v40"/></g><path d="M75 205v-90h40v-45h40v40h46v42h50v47h44" fill="none" stroke="#bde9ce" stroke-width="2" stroke-dasharray="5 5" opacity=".8"/><circle cx="75" cy="205" r="4" fill="#bde9ce"/><g transform="translate(272 185)"><rect x="-8" y="-9" width="45" height="25" rx="5" fill="#142a24" stroke="#bde9ce"/><rect x="-4" y="-14" width="10" height="7" rx="2" fill="#bde9ce"/><rect x="-4" y="14" width="10" height="7" rx="2" fill="#bde9ce"/><circle cx="27" cy="3" r="4" fill="#bde9ce"/><path d="M38-15q28 20 0 40 M47-23q38 29 0 57" stroke="#bde9ce" opacity=".4" fill="none"/></g>`;
else if(type==='wave')body=`<path d="M30 150h320 M55 35v195" stroke="#476457" stroke-width="1"/><path d="M30 150C50 150 55 75 75 75S100 225 122 225S150 75 174 75S200 225 225 225S250 75 275 75S300 225 325 225S344 130 352 130" fill="none" stroke="#bde9ce" stroke-width="2"/><path d="M30 150c30-80 55 80 85 0s55 80 85 0s55 80 85 0s40 70 68 0" fill="none" stroke="#66a5a5" stroke-width="1.5" opacity=".45"/>`;
else if(type==='line')body=`<path d="M50 205V95q0-50 60-50h120q80 0 80 70t-80 65h-80q-35 0-35 40" stroke="#577366" stroke-width="23" fill="none"/><path d="M50 205V95q0-50 60-50h120q80 0 80 70t-80 65h-80q-35 0-35 40" stroke="#bde9ce" stroke-width="1.5" stroke-dasharray="6 6" fill="none"/><g transform="translate(208 22)"><rect width="50" height="46" rx="7" fill="#18352a" stroke="#bde9ce"/><rect x="-6" y="5" width="9" height="14" rx="2" fill="#bde9ce"/><rect x="-6" y="28" width="9" height="14" rx="2" fill="#bde9ce"/><rect x="44" y="5" width="9" height="14" rx="2" fill="#bde9ce"/><rect x="44" y="28" width="9" height="14" rx="2" fill="#bde9ce"/><path d="M18 15l17 8-17 8z" fill="#bde9ce"/></g>`;
else if(type==='code')body=`<rect x="50" y="45" width="280" height="185" rx="9" fill="#16211e" stroke="#526c5e"/><path d="M50 76h280" stroke="#526c5e"/><g fill="#87ad97"><circle cx="68" cy="61" r="3"/><circle cx="80" cy="61" r="3"/><circle cx="92" cy="61" r="3"/></g><path d="M95 110h80 M110 134h130 M110 156h100 M95 182h65" stroke="#bde9ce" stroke-width="3"/><path d="M253 169l-10 10 10 10 M281 169l10 10-10 10 M270 164l-7 29" stroke="#83bcb1" fill="none" stroke-width="2"/>`;
else if(type==='map')body=`<g fill="none" stroke="#405c50"><circle cx="188" cy="143" r="98"/><circle cx="188" cy="143" r="68"/><circle cx="188" cy="143" r="35"/><path d="M188 32v220 M77 143h222"/></g><path d="M85 200l35-60 40 14 35-74 50 30 30-35" stroke="#bde9ce" stroke-width="2" fill="none"/><g fill="#bde9ce"><circle cx="85" cy="200" r="4"/><circle cx="120" cy="140" r="4"/><circle cx="160" cy="154" r="4"/><circle cx="195" cy="80" r="4"/><circle cx="245" cy="110" r="4"/></g>`;
else body=`<g fill="none" stroke="#607e6d" stroke-width="2"><rect x="130" y="83" width="118" height="104" rx="8"/><path d="M40 75h55v35h35 M248 110h45V60h40 M40 195h55v-35h35 M248 160h50v55h40 M165 83V45 M208 83V45 M165 187v47 M208 187v47"/></g><rect x="157" y="105" width="62" height="59" rx="3" fill="#223f2e" stroke="#bde9ce"/><text x="187" y="139" text-anchor="middle" fill="#bde9ce" font-size="11" font-family="monospace">ESP32</text><g fill="#bde9ce"><circle cx="40" cy="75" r="4"/><circle cx="333" cy="60" r="4"/><circle cx="40" cy="195" r="4"/><circle cx="338" cy="215" r="4"/></g>`;
return `<svg class="art-svg" aria-label="Concept illustration" role="img" viewBox="0 0 380 270"><defs><pattern id="g-${id}" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#8da79b" opacity=".2"/></pattern></defs><rect width="380" height="270" fill="url(#g-${id})"/>${body}</svg>`;}
function card(p){return `<a class="project-card" href="#project/${p.id}"><div class="card-art">${art(p.art,p.id)}</div><div class="card-content"><div class="card-meta"><span>${esc(p.category)}</span><span>${esc(p.period)}</span></div><h3>${esc(p.name)} <span class="arrow">↗</span></h3><p>${esc(p.summary)}</p>${tags(p.tags)}</div></a>`;}
function nav(workspace=false){const path=location.hash.slice(1)||'home';return `<div class="notice">${siteConfig.deploymentMode==='private-review'?'PRIVATE REVIEW':'LOCAL WORKSPACE EDITION'} · Workspace data stays in this browser · Cloud services not connected <a href="#workspace/settings">Setup ↗</a></div><header class="topbar"><div class="container nav"><a class="brand" href="#home" aria-label="Yash Joshi home"><span class="monogram">YJ<span style="display:none"></span></span><span class="brand-stack">Yash Joshi<span>ENGINEERING PORTFOLIO</span></span></a><nav class="navlinks" aria-label="Main navigation"><a href="#home" class="${path==='home'?'active':''}">Overview</a><a href="#projects" class="${path.startsWith('project')?'active':''}">Projects</a><a href="#notes" class="${path==='notes'?'active':''}">Notes & articles</a><a href="#updates" class="${path==='updates'?'active':''}">Updates</a><a class="optional" href="${profile.github}" target="_blank" rel="noopener noreferrer">GitHub ↗</a></nav><a class="button quiet" href="${workspace?'#home':'#workspace'}">${workspace?'View portfolio ↗':'Open workspace ↗'}</a></div></header>`;}
const foot=()=>`<footer class="container foot"><span>Yash Joshi · Electronics & Communication Engineering</span><span>Built around the work. Updated as I learn.</span><div class="motion-tools"><button data-motion-toggle aria-pressed="false">Ⅱ Pause motion</button><button data-install>Install app ↗</button></div><a href="${profile.github}" target="_blank" rel="noopener noreferrer">GitHub ↗</a></footer>`;
function home(){return `<div class="container"><section class="hero"><div><div class="eyebrow"><span class="dot"></span>Electronics · Robotics · Software</div><div class="technical-counter">BUILD / EXPERIMENT / ITERATE</div><h1><span class="name-gradient">Yash Joshi.</span></h1><div class="role">Electronics. Code.<br><span class="accent">A constant curiosity.</span></div><p>${profile.summary}</p><div class="hero-kicker"><span></span>MAKING SENSE OF SIGNALS & SYSTEMS</div><div class="actions"><a class="button primary" href="#projects">Explore my projects <span class="arrow">↗</span></a>${button('Print résumé ↓','print','quiet')}</div><div class="hero-meta"><div><strong>GBPIET, Pauri Garhwal</strong>B.Tech · Electronics & Communication</div><div><strong>${profile.location}</strong>Engineering student</div></div><div class="print-only">GitHub: ${profile.github}</div></div>${motionPanel()}</section><div class="discipline-strip"><span>Embedded systems</span><span>Robotics & control</span><span>Signal processing</span><span>Software development</span></div><section class="section"><div class="section-head"><div><div class="eyebrow">01 / Selected work</div><h2>From ideas to working systems.</h2><p>Hardware, algorithms and the lessons in between.</p></div><a class="text-link" href="#projects">All 8 entries ↗</a></div><div class="grid3">${[projects[0],projects[4],projects[7]].map(card).join('')}</div></section><section class="section"><div class="section-head"><div><div class="eyebrow">02 / Foundation</div><h2>Education & technical skills</h2></div></div><div class="two-col"><div class="panel"><div class="panel-label">Education</div><div class="education-top"><div><h3>B.Tech, Electronics &<br>Communication Engineering</h3><p>GBPIET · Uttarakhand Technical University<br>Pauri Garhwal</p></div><div class="metric"><strong>7.97</strong><small>CGPA / 10 · résumé value</small></div></div><div class="semester-row">${profile.semesters.map(x=>`<div><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div><details class="subject-list"><summary>Core subject highlights</summary><table><thead><tr><th>Subject</th><th>Grade</th><th>Marks</th></tr></thead><tbody>${profile.subjects.map(x=>`<tr>${x.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></details></div><div>${skills.map(x=>`<div class="skill-row"><span>${esc(x[0])}</span>${tags(x.slice(1))}</div>`).join('')}</div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">03 / Project résumé</div><h2>A closer look at the work</h2><p>Projects and learning activities from my supplied résumé.</p></div></div><div class="resume-list">${projects.map(p=>`<article class="resume-entry"><small>${esc(p.period)} · ${esc(p.type.toUpperCase())}</small><h3 style="margin-top:11px"><a href="#project/${p.id}">${esc(p.name)} ↗</a></h3><p>${esc(p.stack)}</p><ul class="bullets">${p.details.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></article>`).join('')}</div></section><section class="section two-col"><div><div class="eyebrow">04 / Community</div><h2>Learning, then sharing.</h2><p>Core member & contributor · EtHOS, GBPIET<br><small>2023–Present · as listed in résumé</small></p><ul class="bullets">${leadership.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><div class="eyebrow">05 / Interests</div><h2>What I want to explore</h2><p>Areas of interest that connect my electronics background with future work.</p>${tags(profile.interests)}<div class="spacer panel"><h3>Research & future goals</h3><p>My workspace keeps emerging ideas, reading notes and milestones together. Approved announcements appear in the updates section.</p><a class="text-link" href="#updates">See published updates ↗</a></div></div></section><section class="section no-print"><div class="section-head"><div><div class="eyebrow">06 / Development</div><h2>Code & recent activity</h2></div>${pill('Public GitHub · on demand','gray')}</div><div class="panel two-col"><div><h3>@yashjoshi1827</h3><p>Explore my repositories and recent public work on GitHub.</p><a class="button quiet" href="${profile.github}" target="_blank" rel="noopener noreferrer">Open GitHub profile ↗</a></div><div><p>Load public repositories and their latest commits directly from GitHub. Your private repositories are never requested.</p>${button('Refresh public activity ↻','github-refresh','quiet')}<div id="githubResults" aria-live="polite"></div></div></div></section></div>`;}
function projectPage(id){const p=projects.find(p=>p.id===id);if(!p)return head('404','Project not found','Choose an entry from the projects page.');const logs=publicRecords('logs').filter(x=>x.published.project===id).sort((a,b)=>b.updated.localeCompare(a.updated));return `<div class="container"><div class="page-heading"><a class="back" href="#projects">← All projects</a></div><section class="project-detail-header"><div><div class="eyebrow">${esc(p.category)} / ${esc(p.period)}</div><h1>${esc(p.name)}</h1><p>${esc(p.summary)}</p>${tags(p.tags)}</div><div class="hero-art">${art(p.art,'detail')}</div></section><div class="two-col"><div class="panel"><h3>Work & contribution</h3><ul class="bullets">${p.details.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></div><div class="panel"><h3>Technical stack</h3><p>${esc(p.stack)}</p><h3 style="margin-top:25px">Reports & repository</h3><p>Project-specific links and reports have not been attached yet.</p><a class="text-link" href="${profile.github}" target="_blank" rel="noopener noreferrer">Browse GitHub profile ↗</a></div></div><section class="section"><div class="section-head"><div><h2>Project timeline</h2><p>Approved snapshots of project updates.</p></div><a class="button small" href="#workspace/journal?project=${id}">Open project journal ↗</a></div>${logs.length?`<div class="record-list">${logs.map(l=>logCard(l,true)).join('')}</div>`:empty('A place for the process','No updates have been published to this preview yet. The project journal keeps objectives, experiments, results and next steps together.')}</section></div>`;}
function galleryPublic(){const fs=state.files.filter(f=>f.published&&(f.type.startsWith('image/')||f.type.startsWith('video/')));return `<div class="container">${head('Gallery','A visual record','Selected images and videos published to this browser’s portfolio preview.')}<div class="callout">This is a local preview. Publishing here does not upload media or make it publicly accessible.</div>${fs.length?`<div class="file-grid">${fs.map(f=>fileCard(f,true)).join('')}</div>`:empty('No media published yet','Add a photo or recording in the workspace, then publish a snapshot to this preview.')}<div class="spacer"></div></div>`;}
function notesPublic(){const ns=publicRecords('notes');return `<div class="container">${head('Knowledge / Writing','Notes & technical articles','Engineering notes, programming practice and ideas, published when ready.')}<div class="filterbar">${['All','Engineering notes','MATLAB','Programming','Articles','References','Research ideas'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>${ns.length?`<div class="record-list">${ns.filter(n=>filter==='All'||n.published.category===filter).map(n=>`<article class="record"><div class="record-meta">${esc(n.published.category)} · ${date(n.published.at)}</div><h3>${esc(n.published.title)}</h3><div class="rendered">${markdown(n.published.markdown)}</div></article>`).join('')}</div>`:empty('The notebook is ready','No notes or articles have been published yet. Private drafts live in the workspace.')}<div class="spacer"></div></div>`;}
function updatesPublic(){const a=publicRecords('announcements');return `<div class="container">${head('Progress / What’s next','Updates & announcements','Upcoming work and approved project milestones. Private reminders remain in the workspace.')}<div class="two-col"><section><h2>Announcements</h2>${a.length?a.sort((a,b)=>b.updated.localeCompare(a.updated)).map(x=>`<article class="record"><small>${date(x.published.at)}</small><h3>${esc(x.published.title)}</h3><p>${esc(x.published.body)}</p></article>`).join(''):empty('No announcements yet','Upcoming work will appear here after it is reviewed and published to the preview.')}</section><section><h2>Project updates</h2>${publicRecords('logs').length?publicRecords('logs').map(x=>logCard(x,true)).join(''):empty('A timeline of the work','Project updates can include what worked, what did not, and the next experiment.')}</section></div><div class="section"><a class="text-link" href="#gallery">Explore the gallery ↗</a></div></div>`;}
function sidebar(page){return `<aside class="side"><div class="side-label">YOUR WORKSPACE</div>${[['','◈','Dashboard'],['journal','⌁','Project journal'],['notes','▤','Notes & writing'],['files','▧','Files & gallery'],['goals','◎','Goals & reminders'],['announcements','↗','Announcements'],['settings','⚙','Setup & export']].map(([p,i,t])=>`<a href="#workspace${p?'/'+p:''}" class="${p===page?'active':''}"><i>${i}</i>${t}</a>`).join('')}<div class="side-note"><span class="dot"></span> Browser-only prototype<br>No cloud sync or independent account is connected.</div></aside>`;}
function dashboard(){const due=state.goals.filter(g=>!g.done&&g.due&&new Date(g.due+'T23:59:59')<new Date());return `${head('Workspace / Overview','Good work starts with a record.','Capture the experiment, keep the result, decide what to share.')}<div class="dashboard-actions">${button('+ Project update','new-log','primary')}${button('+ Capture an idea','new-note')}${button('◉ Record a video','record')}${button('+ Add a goal','new-goal')}</div><div class="stat-grid"><div class="stat"><span>Project updates</span><strong>${state.logs.length}</strong></div><div class="stat"><span>Notes & drafts</span><strong>${state.notes.length}</strong></div><div class="stat"><span>Open goals</span><strong>${state.goals.filter(g=>!g.done).length}</strong></div></div>${due.length?`<div class="callout warning">${due.length} goal${due.length===1?' is':'s are'} past the target date. <a href="#workspace/goals">Review goals →</a></div>`:''}<div class="two-col"><section><div class="section-head"><h2>Recent project updates</h2><a class="text-link" href="#workspace/journal">View all ↗</a></div>${state.logs.length?state.logs.slice().sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,3).map(l=>logCard(l)).join(''):empty('Start your engineering journal','Record an objective, the work, results, problems, and what comes next.',button('Write first update','new-log','small'))}</section><section><div class="section-head"><h2>Continue a project</h2></div>${projects.slice(0,3).map(p=>`<a class="record" style="display:block;margin-bottom:12px" href="#workspace/journal?project=${p.id}"><div class="record-meta">${esc(p.category)}</div><h3>${esc(p.name)} ↗</h3><small>${esc(p.subtitle)}</small></a>`).join('')}</section></div><div class="callout spacer">Drafts and media are saved only on this browser and device. Export text records and download important files before clearing browser data.</div>`;}
function logCard(l,pub=false){const v=pub?l.published:l;return `<article class="record"><div class="record-meta"><span>${esc(projectName(pub?v.project:l.project))}</span><span>${date(pub?v.at:l.updated)}</span>${pill(pub?'Published snapshot':l.published?'Draft + published snapshot':'Private draft',pub?'':'gray')}</div><h3>${esc(v.title)}</h3>${fields.map(f=>v[f]?`<details ${f==='objective'?'open':''}><summary>${labels[f]}</summary><p>${esc(v[f])}</p></details>`:'').join('')}${!pub?`<div class="actions">${button('Edit','edit-log','small',`data-id="${l.id}"`)}${button(l.published?'Update preview snapshot':'Publish to preview','publish-log','small',`data-id="${l.id}"`)}${l.published?button('Unpublish','unpublish-log','small quiet',`data-id="${l.id}"`):''}${button('Delete draft','delete-log','small quiet',`data-id="${l.id}"`)}</div>`:''}</article>`;}
function journal(){const pid=new URLSearchParams(location.hash.split('?')[1]||'').get('project')||'';const logs=state.logs.filter(l=>!pid||l.project===pid).sort((a,b)=>b.updated.localeCompare(a.updated));return `${head('Workspace / Projects',pid?esc(projectName(pid)):'Project journal','Keep a guided record of objectives, work, results, problems and next steps.')}<div class="dashboard-actions">${button('+ New update','new-log','primary',`data-project="${pid}"`)}${button('◉ Record video','record','',`data-project="${pid}"`)}</div><div class="form-row"><label for="projectFilter">Project</label><select id="projectFilter">${optionProjects(pid)}</select></div>${logs.length?`<div class="record-list">${logs.map(l=>logCard(l)).join('')}</div>`:empty('No updates for this project yet','Your next experiment can be the first entry.',button('Write an update','new-log','small',`data-project="${pid}"`))}`;}
function notesWorkspace(){return `${head('Workspace / Notebook','Notes & writing','A simple editor for engineering notes, code practice, reading and research ideas.')}<div class="dashboard-actions">${button('+ New note','new-note','primary')}</div><input class="search" id="noteSearch" type="search" placeholder="Search notes…" aria-label="Search notes" value="${esc(search)}"><div id="noteResults">${noteResults()}</div>`;}
function noteResults(){const ns=state.notes.filter(n=>(n.title+' '+n.markdown+' '+n.category).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.updated.localeCompare(a.updated));return ns.length?`<div class="record-list">${ns.map(n=>`<article class="record"><div class="record-meta"><span>${esc(n.category)}</span><span>${date(n.updated)}</span>${pill(n.published?'Draft + published snapshot':'Private draft','gray')}</div><h3>${esc(n.title)}</h3><p>${esc(n.markdown.slice(0,180))}${n.markdown.length>180?'…':''}</p><div class="actions">${button('Edit note','edit-note','small',`data-id="${n.id}"`)}${button(n.published?'Update preview snapshot':'Publish to preview','publish-note','small',`data-id="${n.id}"`)}${n.published?button('Unpublish','unpublish-note','small quiet',`data-id="${n.id}"`):''}${button('Delete','delete-note','small quiet',`data-id="${n.id}"`)}</div></article>`).join('')}</div>`:empty('A notebook for your engineering work','Add MATLAB practice, programming notes, reading summaries or a research question.');}
function fileCard(f,pub=false){return `<article class="file-card"><div class="file-media" data-media="${f.id}"></div><h3>${esc(f.name)}</h3><p>${esc(f.category)} · ${bytes(f.size)}<br>${esc(projectName(f.project))} · ${date(f.created)}</p>${pill(pub?'Published to this local preview':f.published?'Preview published · device copy':'Private · device only',pub?'':'gray')}<div class="actions">${button('Download','download-file','small',`data-id="${f.id}"`)}${!pub?`${f.category!=='Marksheets'&&f.category!=='Private documents'?button(f.published?'Unpublish':'Publish to preview',f.published?'unpublish-file':'publish-file','small',`data-id="${f.id}"`):''}${button('Delete','delete-file','small quiet',`data-id="${f.id}"`)}`:''}</div></article>`;}
function filesWorkspace(){return `${head('Workspace / Files','Files, gallery & recordings','Keep local files with the project or subject they belong to.')}<div class="dashboard-actions">${button('+ Add files','add-files','primary')}${button('◉ Record video','record')}</div><div class="callout">Google Drive, Google Photos and cloud uploads are not connected. Files added here stay on this device. Private document sharing will require the protected backend.</div>${state.files.length?`<div class="file-grid">${state.files.slice().sort((a,b)=>b.created.localeCompare(a.created)).map(f=>fileCard(f)).join('')}</div>`:empty('Keep the evidence with the work','Add a diagram, MATLAB file, report, photo or project recording. Nothing is sent to a cloud account.')}`;}
function goalsWorkspace(){return `${head('Workspace / Direction','Goals & private reminders','Set a next step and a target date. Goals remain private.')}<div class="dashboard-actions">${button('+ New goal','new-goal','primary')}</div><div class="callout">This preview shows reminders when you open the workspace. Use “Add to calendar” for a downloadable calendar reminder. Background push and email reminders are not connected.</div>${state.goals.length?`<div class="record-list">${state.goals.slice().sort((a,b)=>(a.done-b.done)||((a.due||'9999').localeCompare(b.due||'9999'))).map(g=>`<article class="record ${!g.done&&g.due&&new Date(g.due+'T23:59:59')<new Date()?'reminder-due':''}"><div class="record-meta">${pill(g.done?'Completed':'Private goal',g.done?'':'gray')}<span>${g.due?'Target: '+date(g.due+'T12:00:00'):'No target date'}</span></div><h3>${esc(g.title)}</h3><p>${esc(g.body||'')}</p><div class="actions">${button(g.done?'Reopen':'Mark complete','toggle-goal','small',`data-id="${g.id}"`)}${button('Edit','edit-goal','small quiet',`data-id="${g.id}"`)}${g.due?button('Add to calendar ↓','calendar','small quiet',`data-id="${g.id}"`):''}${button('Delete','delete-goal','small quiet',`data-id="${g.id}"`)}</div></article>`).join('')}</div>`:empty('What do you want to work toward?','Create a private milestone, study goal, experiment or application deadline.')}`;}
function announcementWorkspace(){return `${head('Workspace / Sharing','Public announcements','Write an upcoming-work announcement, review it, then publish a snapshot.')}<div class="dashboard-actions">${button('+ Draft announcement','new-announcement','primary')}</div><div class="callout">Publishing updates only this browser’s portfolio preview. Nothing is posted to GitHub, social media or a public website.</div>${state.announcements.length?`<div class="record-list">${state.announcements.map(a=>`<article class="record"><div class="record-meta">${pill(a.published?'Draft + published snapshot':'Private draft','gray')}<span>${date(a.updated)}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.body)}</p><div class="actions">${button('Edit','edit-announcement','small',`data-id="${a.id}"`)}${button(a.published?'Update preview snapshot':'Publish to preview','publish-announcement','small',`data-id="${a.id}"`)}${a.published?button('Unpublish','unpublish-announcement','small quiet',`data-id="${a.id}"`):''}${button('Delete','delete-announcement','small quiet',`data-id="${a.id}"`)}</div></article>`).join('')}</div>`:empty('Share what is coming next','Announcements are separate from private goals and reminders.')}`;}
function settings(){return `${head('Workspace / Setup','An honest view of what is connected.','This edition has a browser-local workspace. Your independent account and cloud services still need provisioning.')}<div class="panel">${[['Independent email/password','Not connected','Firebase Authentication is proposed for the production app. This preview does not collect passwords or simulate a login.'],['Google Drive / Docs','Not connected','Select and import files after Google account authorization is configured. Public reports will use approved copies.'],['Google Photos','Not connected','Use Google’s supported picker for selected photos and videos. Full automatic existing-library synchronization is not promised.'],['GitHub','Public reads on demand','Use Refresh public activity on the home page to load public repositories and recent commits. No private repository access or writes. Live API responses have not been verified in this environment.'],['Cloud storage & upload queue','Device storage only','Local drafts and media work in this browser. Cross-device sync, resumable cloud uploads and backups need the backend.'],['Restricted sharing','Not connected','Expiring and revocable links require protected server-side file access. This preview does not generate insecure substitute links.'],['Goal notifications','In-app + calendar export','Private goals and public announcement drafts are separate. Email and background push delivery still require implementation.']].map(([t,s,d])=>`<div class="setup-row"><div><h3>${t}</h3><p>${d}</p></div>${pill(s,'gray')}</div>`).join('')}</div><section class="section"><h2>Résumé details to confirm</h2><ul class="bullets"><li>The source says “2nd Year” and “Expected May 2027”. Confirm your current year and expected graduation date.</li><li>CGPA 7.97 and semester results are shown as supplied. Confirm whether they are current.</li><li>The email and phone in the document are placeholders. They are not displayed as real contact information.</li><li>Project dates and EtHOS activity dates come from your résumé; confirm any changes.</li></ul><p class="help">The enrollment number and placeholder contact details are omitted. Use Print résumé on the home page to generate a PDF of the displayed portfolio résumé.</p></section><section class="section"><h2>Export & device storage</h2><p>Export includes your text records, approved snapshots and file metadata. Download media separately. To publish approved text snapshots on Vercel, run scripts/publish-content.mjs against your export, review the generated published-content.json, then commit and push. Private drafts and goals are excluded by that script.</p><div class="actions">${button('Export text records ↓','export','primary')}${button('Import text records','import')}${button('Check device storage','storage','quiet')}</div><p id="storageInfo" class="help"></p><p class="help">Do not treat browser-only storage as a permanent backup. Offline access to a previously opened preview can remain available on this device.</p></section>`;}
async function render(){urls.forEach(u=>URL.revokeObjectURL(u));urls=[];route=location.hash.slice(1).split('?')[0]||'home';const ws=route.startsWith('workspace');let body='';if(ws){const page=route.split('/')[1]||'';const views={'':dashboard,journal,notes:notesWorkspace,files:filesWorkspace,goals:goalsWorkspace,announcements:announcementWorkspace,settings};body=`<div class="workspace">${sidebar(page)}<main id="main" class="workspace-main">${storageError?'<div class="callout warning">Device storage is unavailable. Changes cannot be saved in this browser.</div>':''}${(views[page]||dashboard)()}</main></div>`;}else{if(route==='home')body=home();else if(route==='projects')body=`<div class="container">${head('Portfolio / Projects','Built. Tested. Learned.','Projects and learning activities across electronics, robotics, signal processing and software.')}<div class="filterbar">${['All','Robotics','Embedded','MATLAB','Software','Research'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="grid3">${projects.filter(p=>filter==='All'||p.category===filter).map(card).join('')}</div><div class="section"></div></div>`;else if(route.startsWith('project/'))body=projectPage(route.split('/')[1]);else if(route==='notes')body=notesPublic();else if(route==='updates')body=updatesPublic();else if(route==='gallery')body=galleryPublic();else body=`<div class="container">${head('404','Page not found')}<a class="button" href="#home">Back to portfolio</a></div>`;body=`<main id="main">${body}</main>`;}$('#app').innerHTML=nav(ws)+body+foot();await hydrateMedia();mountMotion();}
async function hydrateMedia(){for(const el of document.querySelectorAll('[data-media]')){const f=state.files.find(x=>x.id===el.dataset.media);if(!f||!/^image\/|^video\//.test(f.type))continue;try{const entry=await tx('blobs','get',f.id);if(!entry||!el.isConnected)continue;const u=URL.createObjectURL(entry.blob);urls.push(u);if(f.type.startsWith('image/')){const img=document.createElement('img');img.src=u;img.alt=f.name;img.loading='lazy';el.append(img);}else{const v=document.createElement('video');v.controls=true;v.preload='metadata';v.src=u;el.append(v);}}catch{}}}
function modal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').showModal();}
function closeModal(){if(recorder?.state==='recording'){toast('Stop recording before closing.');return;}stopStream();$('#modal').close();}
const row=(id,label,content)=>`<div class="form-row"><label for="${id}">${label}</label>${content}</div>`;
const textfield=(id,value='',required=false)=>`<input id="${id}" name="${id}" value="${esc(value)}" ${required?'required':''} maxlength="220">`;
const textarea=(id,value='',required=false)=>`<textarea id="${id}" name="${id}" ${required?'required':''}>${esc(value)}</textarea>`;
const formend=(label='Save private draft')=>`<div class="actions"><button class="button primary" type="submit">${label}</button><button class="button quiet" type="button" data-action="close">Cancel</button></div></form>`;
function editLog(id,project){const l=state.logs.find(x=>x.id===id)||{};modal(id?'Edit project update':'New project update',`<form id="logForm" data-id="${id||''}">${row('title','Update title',textfield('title',l.title,true))}${row('project','Project',`<select id="project" name="project" required><option value="">Select a project</option>${projects.map(p=>`<option value="${p.id}" ${p.id===(l.project||project)?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`)}${fields.map(f=>row(f,labels[f],textarea(f,l[f]))).join('')}<p class="help">Saving leaves any published snapshot unchanged.</p>${formend()}`);}
function inline(text){return esc(text).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>');}
function markdown(text){let code=false,items=false,out=[];for(const line of String(text||'').split('\n')){if(line.startsWith('```')){if(items){out.push('</ul>');items=false;}out.push(code?'</code></pre>':'<pre><code>');code=!code;continue;}if(code){out.push(esc(line)+'\n');continue;}if(line.startsWith('- ')){if(!items){out.push('<ul>');items=true;}out.push('<li>'+inline(line.slice(2))+'</li>');continue;}if(items){out.push('</ul>');items=false;}if(line.startsWith('## '))out.push('<h2>'+inline(line.slice(3))+'</h2>');else if(line.trim())out.push('<p>'+inline(line)+'</p>');else out.push('<br>');}if(code)out.push('</code></pre>');if(items)out.push('</ul>');return out.join('');}
function toMarkdown(root){function walk(n){if(n.nodeType===3)return n.textContent;if(n.nodeType!==1)return '';const x=[...n.childNodes].map(walk).join('');switch(n.tagName){case 'STRONG':case 'B':return '**'+x+'**';case 'EM':case 'I':return '*'+x+'*';case 'H2':return '\n## '+x+'\n';case 'LI':return '\n- '+x;case 'PRE':return '\n```\n'+n.textContent+'\n```\n';case 'CODE':return '`'+x+'`';case 'BR':return '\n';case 'DIV':case 'P':return x+'\n';case 'SCRIPT':case 'STYLE':return '';default:return x;}}return [...root.childNodes].map(walk).join('').replace(/\n{3,}/g,'\n\n').trim();}
function editorHTML(md){return `<div class="editor-toolbar"><button type="button" data-action="format" data-format="bold"><b>B</b></button><button type="button" data-action="format" data-format="italic"><i>I</i></button><button type="button" data-action="format" data-format="heading">H2</button><button type="button" data-action="format" data-format="list">List</button></div><div class="rich-editor" id="richEditor" contenteditable="true" role="textbox" aria-label="Note content" aria-multiline="true" data-placeholder="What did you learn or want to explore?">${markdown(md)}</div>`;}
function editNote(id){const n=state.notes.find(x=>x.id===id)||{};editorMode='visual';modal(id?'Edit note':'New note',`<form id="noteForm" data-id="${id||''}">${row('title','Title',textfield('title',n.title,true))}<div class="form-grid">${row('category','Section',`<select id="category" name="category">${['Engineering notes','MATLAB','Programming','Articles','References','Research ideas'].map(c=>`<option ${c===n.category?'selected':''}>${c}</option>`).join('')}</select>`)}${row('project','Project',`<select id="project" name="project">${optionProjects(n.project)}</select>`)}</div><div class="filterbar"><button type="button" class="filter active" data-action="editor-mode" data-mode="visual">Visual editor</button><button type="button" class="filter" data-action="editor-mode" data-mode="markdown">Markdown</button></div><div id="editorHost">${editorHTML(n.markdown||'')}</div><p class="help">Preview editor supports headings, bold, italic, lists and code blocks. Advanced equations, tables and document import are planned. Save does not alter an existing published snapshot.</p>${formend()}`);}
function editGoal(id){const g=state.goals.find(x=>x.id===id)||{};modal(id?'Edit private goal':'New private goal',`<form id="goalForm" data-id="${id||''}">${row('title','Goal',textfield('title',g.title,true))}${row('due','Target date',`<input id="due" name="due" type="date" value="${g.due||''}">`)}${row('body','Next action or reminder',textarea('body',g.body))}<p class="help">Private goal. This is not a public announcement.</p>${formend('Save private goal')}`);}
function editAnnouncement(id){const a=state.announcements.find(x=>x.id===id)||{};modal(id?'Edit announcement':'Draft an announcement',`<form id="announcementForm" data-id="${id||''}">${row('title','Announcement title',textfield('title',a.title,true))}${row('body','What is coming next?',textarea('body',a.body,true))}<p class="help">Save as a private draft first. You can then publish a separate snapshot to the portfolio preview.</p>${formend()}`);}
function addFiles(){modal('Add files to this device',`<form id="fileForm">${row('files','Files',`<input id="files" name="files" type="file" multiple required>`)}<div class="form-grid">${row('category','Section',`<select id="category" name="category">${['Project files','Photos & videos','MATLAB','Programming','Engineering notes','References','Marksheets','Private documents'].map(c=>`<option>${c}</option>`).join('')}</select>`)}${row('project','Project',`<select id="project" name="project">${optionProjects()}</select>`)}</div><p class="help">Stored only in this browser. Marksheets and private documents cannot be published from this prototype. No files are uploaded to Google or GitHub.</p>${formend('Save files on device')}`);}
function recordModal(project){recordProject=project||projects[0].id;modal('Record a project update',`${row('recordProject','Project',`<select id="recordProject">${projects.map(p=>`<option value="${p.id}" ${p.id===recordProject?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`)}<video id="cameraPreview" class="camera-preview" muted playsinline autoplay></video><div id="recordStatus" class="record-status">Camera is off. Start when you are ready.</div><div class="actions">${button('Start recording','start-record','primary')}${button('Stop & save','stop-record','','disabled')}${button('Upload an existing video','record-file','quiet')}</div><p class="help">The recording will be saved on this device, ready for a future cloud upload. Keep this screen open while recording. Download a copy after recording for backup.</p>`);}
function stopStream(){stream?.getTracks().forEach(t=>t.stop());stream=null;clearInterval(recordTimer);}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Recording is unavailable in this browser. Upload an existing video instead.');$('[data-action="start-record"]').disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:true});$('#cameraPreview').srcObject=stream;recordChunks=[];const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime,videoBitsPerSecond:2500000}:undefined);recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data);};recorder.onerror=e=>{$('#recordStatus').textContent='Recording error. Try a local camera app and upload the result.';stopStream();};recorder.onstop=async()=>{clearInterval(recordTimer);const blob=new Blob(recordChunks,{type:recorder.mimeType||'video/webm'});stopStream();const ext=blob.type.includes('mp4')?'mp4':'webm';try{await saveFile(blob,projectName(recordProject)+' '+new Date().toISOString().slice(0,10)+'.'+ext,'Photos & videos',recordProject);$('#modal').close();location.hash='workspace/files';await render();toast('Recording saved on this device. Download a backup copy.');}catch(err){const u=URL.createObjectURL(blob);$('#recordStatus').innerHTML=`Could not save in browser storage. <a class="button" href="${u}" download="project-recording.${ext}">Download recording now</a>`;urls.push(u);toast('Device storage failed. Download your recording before closing.');}recordChunks=[];};recordProject=$('#recordProject').value;$('#recordProject').disabled=true;recorder.start(1000);recordStarted=Date.now();recordTimer=setInterval(()=>{$('#recordStatus').textContent='Recording · '+Math.floor((Date.now()-recordStarted)/1000)+' seconds · keep this window open';},1000);$('[data-action="stop-record"]').disabled=false;}catch(err){stopStream();$('[data-action="start-record"]').disabled=false;throw err;}}
async function saveFile(blob,name,category,project){const id=crypto.randomUUID();const f={id,name,type:blob.type||'application/octet-stream',size:blob.size,category,project,created:new Date().toISOString(),published:false};await tx('blobs','put',{id,blob});try{await persist('files',f);}catch(err){await tx('blobs','delete',id);throw err;}return f;}
function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}
function calendar(g){const clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const d=g.due.replaceAll('-','');const end=new Date(g.due+'T12:00:00');end.setDate(end.getDate()+1);const endDate=[end.getFullYear(),String(end.getMonth()+1).padStart(2,'0'),String(end.getDate()).padStart(2,'0')].join('');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Yash Engineering Journal//EN','BEGIN:VEVENT','UID:'+g.id+'@yash-journal','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z'),'DTSTART;VALUE=DATE:'+d,'DTEND;VALUE=DATE:'+endDate,'SUMMARY:'+clean(g.title),'DESCRIPTION:'+clean(g.body||''),'BEGIN:VALARM','TRIGGER:-PT12H','ACTION:DISPLAY','DESCRIPTION:Goal reminder','END:VALARM','END:VEVENT','END:VCALENDAR'];download(new Blob([lines.join('\r\n')],{type:'text/calendar'}),'goal-reminder.ics');toast('Calendar file downloaded. Import it into your calendar.');}
async function doAction(action,el){const id=el.dataset.id;const mapping={log:'logs',note:'notes',goal:'goals',announcement:'announcements',file:'files'};
if(action.startsWith('publish-')){const kind=action.slice(8),store=mapping[kind],v=state[store].find(x=>x.id===id);if(!v)return;modal('Review before publishing',`<p>This creates a snapshot in this browser’s portfolio preview. It does not publish to the internet.</p><div class="record"><h3>${esc(v.title||v.name)}</h3>${kind==='note'?`<div class="rendered">${markdown(v.markdown)}</div>`:kind==='log'?fields.map(f=>v[f]?`<h4>${labels[f]}</h4><p>${esc(v[f])}</p>`:'').join(''):`<p>${esc(v.body||v.category||'')}</p>`}</div><div class="actions">${button('Publish snapshot to preview','confirm-publish','primary',`data-id="${id}" data-store="${store}"`)}${button('Cancel','close','quiet')}</div>`);return;}
if(action==='confirm-publish'){const store=el.dataset.store,v=state[store].find(x=>x.id===id);if(!v)return;const copy={...v};delete copy.published;v.published=store==='files'?true:{...copy,at:new Date().toISOString()};await persist(store,v);closeModal();await render();toast('Snapshot published to this local preview.');return;}
if(action.startsWith('unpublish-')){const store=mapping[action.slice(10)],v=state[store].find(x=>x.id===id);v.published=null;await persist(store,v);await render();toast('Removed from portfolio preview.');return;}
if(action.startsWith('delete-')){const store=mapping[action.slice(7)],v=state[store].find(x=>x.id===id);modal('Delete this local record?',`<p>${esc(v.title||v.name)} will be removed from this browser, including its preview snapshot. This does not change any external source.</p><div class="actions">${button('Delete local record','confirm-delete','danger',`data-store="${store}" data-id="${id}"`)}${button('Keep it','close','quiet')}</div>`);return;}
switch(action){case 'confirm-delete':await tx(el.dataset.store,'delete',id);if(el.dataset.store==='files')await tx('blobs','delete',id);await load();closeModal();await render();toast('Local record deleted.');break;case 'new-log':editLog(null,el.dataset.project);break;case 'edit-log':editLog(id);break;case 'new-note':editNote();break;case 'edit-note':editNote(id);break;case 'new-goal':editGoal();break;case 'edit-goal':editGoal(id);break;case 'new-announcement':editAnnouncement();break;case 'edit-announcement':editAnnouncement(id);break;case 'close':closeModal();break;case 'add-files':addFiles();break;case 'record':recordModal(el.dataset.project);break;case 'record-file':closeModal();addFiles();$('#files').accept='video/*';$('#category').value='Photos & videos';$('#project').value=recordProject;break;case 'start-record':await startRecording();break;case 'stop-record':if(recorder?.state==='recording'){el.disabled=true;$('#recordStatus').textContent='Saving recording on this device…';recorder.stop();}break;case 'download-file':{const f=state.files.find(x=>x.id===id),b=await tx('blobs','get',id);if(!b)throw new Error('This file is not available on this device.');download(b.blob,f.name);break;}case 'toggle-goal':{const g=state.goals.find(x=>x.id===id);g.done=!g.done;await persist('goals',g);await render();break;}case 'calendar':calendar(state.goals.find(x=>x.id===id));break;case 'print':window.print();break;case 'github-refresh':await loadGithub();break;case 'format':{const editor=$('#richEditor');if(!editor)return;editor.focus();const f=el.dataset.format;if(f==='heading')document.execCommand('formatBlock',false,'h2');else if(f==='list')document.execCommand('insertUnorderedList');else document.execCommand(f);break;}case 'editor-mode':{if(editorMode===el.dataset.mode)return;const md=editorMode==='visual'?toMarkdown($('#richEditor')):$('#markdownEditor').value;editorMode=el.dataset.mode;$('#editorHost').innerHTML=editorMode==='visual'?editorHTML(md):`<textarea id="markdownEditor" aria-label="Markdown content" style="min-height:280px;font-family:monospace">${esc(md)}</textarea>`;document.querySelectorAll('[data-action="editor-mode"]').forEach(b=>b.classList.toggle('active',b.dataset.mode===editorMode));break;}case 'export':{const payload={format:'yash-journal-text-v1',exportedAt:new Date().toISOString(),records:state,warning:'File metadata only. Download binary attachments separately.'};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),'yash-journal-text-export.json');toast('Text records exported. Media bytes are not included.');break;}case 'import':modal('Import text records',`<form id="importForm">${row('importFile','Export JSON',`<input type="file" id="importFile" name="importFile" accept="application/json" required>`)}<p class="help">Imported items get new IDs and stay private. File metadata is not imported because the binary files must be added separately.</p>${formend('Import as private drafts')}`);break;case 'storage':{const s=await navigator.storage?.estimate?.();$('#storageInfo').textContent=s?'Browser usage: '+bytes(s.usage||0)+' of approximately '+bytes(s.quota||0)+'. This quota is controlled by the browser.':'Storage estimate unavailable.';break;}}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{await doAction(el.dataset.action,el);}catch(err){toast(err.message||'The action could not be completed.');}}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;await render();}});
document.addEventListener('input',e=>{if(e.target.id==='noteSearch'){search=e.target.value;$('#noteResults').innerHTML=noteResults();}});
document.addEventListener('change',e=>{if(e.target.id==='projectFilter')location.hash='workspace/journal'+(e.target.value?'?project='+e.target.value:'');});
document.addEventListener('paste',e=>{if(e.target.closest('#richEditor')){e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['logForm','noteForm','goalForm','announcementForm','fileForm','importForm'].includes(f.id))return;e.preventDefault();const submit=f.querySelector('[type="submit"]');submit.disabled=true;const data=Object.fromEntries(new FormData(f)),id=f.dataset.id||crypto.randomUUID(),now=new Date().toISOString();try{if(f.id==='logForm'){const old=state.logs.find(x=>x.id===id)||{};await persist('logs',{...old,...data,id,title:data.title.trim(),updated:now});}else if(f.id==='noteForm'){const old=state.notes.find(x=>x.id===id)||{};await persist('notes',{...old,...data,id,title:data.title.trim(),markdown:editorMode==='visual'?toMarkdown($('#richEditor')):$('#markdownEditor').value,updated:now});}else if(f.id==='goalForm'){const old=state.goals.find(x=>x.id===id)||{done:false};await persist('goals',{...old,...data,id,title:data.title.trim(),updated:now});}else if(f.id==='announcementForm'){const old=state.announcements.find(x=>x.id===id)||{};await persist('announcements',{...old,...data,id,title:data.title.trim(),updated:now});}else if(f.id==='fileForm'){const fs=[...$('#files').files];for(const file of fs){submit.textContent='Saving '+file.name+'…';await saveFile(file,file.name,data.category,data.project);}}else if(f.id==='importForm'){const file=$('#importFile').files[0];if(file.size>5*1024*1024)throw new Error('Text export must be under 5 MB.');const imported=JSON.parse(await file.text());if(imported.format!=='yash-journal-text-v1'||!imported.records)throw new Error('This is not a supported journal export.');const clean=[];for(const [store,props] of Object.entries({logs:['title','project',...fields],notes:['title','project','category','markdown'],goals:['title','body','due'],announcements:['title','body']})){const records=imported.records[store]||[];if(!Array.isArray(records)||records.length>1000)throw new Error('Invalid export size or format.');for(const item of records){if(!item||typeof item.title!=='string')throw new Error('Invalid record in export.');const n={id:crypto.randomUUID(),updated:now,published:null};for(const k of props){if(item[k]!=null&&typeof item[k]!=='string')throw new Error('Invalid text field.');n[k]=(item[k]||'').slice(0,200000);}if(n.project&&!projects.some(p=>p.id===n.project))n.project='';if(store==='goals'){if(n.due&&!/^\d{4}-\d{2}-\d{2}$/.test(n.due))n.due='';n.done=false;}clean.push([store,n]);}}for(const [store,n] of clean)await tx(store,'put',n);await load();}closeModal();await render();toast(f.id==='fileForm'?'Files saved on this device.':f.id==='importForm'?'Text records imported as private drafts.':'Saved on this device. Published snapshots are unchanged.');}catch(err){submit.disabled=false;toast(err.message||'Could not save. Check device storage.');}});
$('#closeModal').addEventListener('click',closeModal);$('#modal').addEventListener('cancel',e=>{if(recorder?.state==='recording'){e.preventDefault();toast('Stop recording before closing.');}else stopStream();});
window.addEventListener('hashchange',()=>{filter='All';search='';render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',e=>{if(recorder?.state==='recording'){e.preventDefault();e.returnValue='';}});
try{db=await dbOpen();await load();}catch(e){storageError=true;}
try{const r=await fetch('./published-content.json',{cache:'no-store'});if(r.ok){const d=await r.json();if(d.format==='yash-public-content-v1'){for(const k of ['logs','notes','announcements'])if(Array.isArray(d[k]))deployedContent[k]=d[k].filter(x=>x&&typeof x.id==='string'&&x.published&&typeof x.published==='object');}}}catch{}
await render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
